<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {api,blob,base} from '../api'
import {getDocument,GlobalWorkerOptions} from 'pdfjs-dist'
import worker from 'pdfjs-dist/build/pdf.worker.min.mjs?url'
GlobalWorkerOptions.workerSrc=worker
const emit=defineEmits<{loaded:[id:string|null]}>()
const props=defineProps<{processId?:string;preview?:any}>(),manifest=ref<any>({version:null,files:[]}),index=ref(0),playing=ref(true),url=ref(''),error=ref(''),cached=ref(false),canvas=ref<HTMLCanvasElement>(),video=ref<HTMLVideoElement>(),page=ref(1),pages=ref(1)
const file=computed(()=>manifest.value.files[index.value]);let timer:ReturnType<typeof setTimeout>,poll:ReturnType<typeof setInterval>,generation=0,pdf:any
async function database(){return new Promise<IDBDatabase>((resolve,reject)=>{const r=indexedDB.open('mes-sop-cache',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function cache(key:string,value?:any){const db=await database();try{return await new Promise<any>((resolve,reject)=>{const tx=db.transaction('files',value===undefined?'readonly':'readwrite');const r=value===undefined?tx.objectStore('files').get(key):tx.objectStore('files').put(value,key);tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
async function load(){const key=base()+'/sop/'+props.processId;let m=props.preview;try{if(!m){m=await api('/api/sop/current/'+props.processId);if(m.version?.id!==manifest.value.version?.id){for(const f of m.files)await cache(base()+'/file/'+f.id,await blob('/api/sop/files/'+f.id));await cache(key,m)}cached.value=false}}catch{m=await cache(key);cached.value=true}if(!m)return;if(m.version?.id===manifest.value.version?.id&&manifest.value.files.length)return;manifest.value=m;index.value=0;await show();emit('loaded',m.version?.id||null)}
function schedule(){clearTimeout(timer);if(playing.value&&file.value&&file.value.contentType!=='video/mp4'&&file.value.contentType!=='video/webm')timer=setTimeout(()=>step(1),file.value.seconds*1000)}
async function renderPdf(){if(!pdf||!canvas.value)return;const p=await pdf.getPage(page.value);const viewport=p.getViewport({scale:1.4});canvas.value.width=viewport.width;canvas.value.height=viewport.height;await p.render({canvasContext:canvas.value.getContext('2d')!,viewport}).promise}
async function show(){const g=++generation;clearTimeout(timer);if(url.value)URL.revokeObjectURL(url.value);url.value='';error.value='';pdf?.destroy();pdf=null;page.value=1;pages.value=1;if(!file.value)return;try{const b:Blob=await cache(base()+'/file/'+file.value.id)||await blob('/api/sop/files/'+file.value.id);if(g!==generation)return;url.value=URL.createObjectURL(b);if(file.value.contentType==='application/pdf'){pdf=await getDocument({data:new Uint8Array(await b.arrayBuffer())}).promise;pages.value=pdf.numPages;await nextTick();await renderPdf()}await nextTick();if(playing.value)video.value?.play().catch(()=>{});schedule()}catch(e:any){error.value=e.message}}
function step(d:number){if(!manifest.value.files.length)return;index.value=(index.value+d+manifest.value.files.length)%manifest.value.files.length;show()}
function toggle(){playing.value=!playing.value;if(playing.value){video.value?.play();schedule()}else{clearTimeout(timer);video.value?.pause()}}
watch(()=>props.processId,load);watch(()=>props.preview,load);onMounted(()=>{load();if(!props.preview)poll=setInterval(load,30000)});onUnmounted(()=>{clearTimeout(timer);clearInterval(poll);generation++;pdf?.destroy();if(url.value)URL.revokeObjectURL(url.value)})
</script>
<template><div class="sop-player"><div class="panelhead"><b>{{manifest.version?.title||'暂无已发布 SOP'}} <span v-if="manifest.version">V{{manifest.version.version}}</span></b><span v-if="cached" class="badge amber">离线缓存</span></div><div class="sop-stage"><p v-if="error" class="offline">{{error}}</p><img v-else-if="file?.contentType.startsWith('image/')" :src="url" :alt="file.name"><canvas v-else-if="file?.contentType==='application/pdf'" ref="canvas"/><video v-else-if="file?.contentType.startsWith('video/')" ref="video" :src="url" controls muted playsinline @ended="playing&&step(1)"/></div><div v-if="file" class="actions"><el-button @click="step(-1)">上一份</el-button><el-button @click="toggle">{{playing?'暂停':'播放'}}</el-button><el-button @click="step(1)">下一份</el-button><small>{{index+1}} / {{manifest.files.length}} · {{file.name}} · {{file.seconds}} 秒</small><template v-if="pages>1"><el-button :disabled="page<=1" @click="page--;renderPdf()">上一页</el-button><span>{{page}} / {{pages}} 页</span><el-button :disabled="page>=pages" @click="page++;renderPdf()">下一页</el-button></template></div></div></template>
